package httpserver

import "strings"

// publicCopyFor supplies complete native-language navigation and landing-page
// copy for the six initial markets. A custom language added in the admin falls
// back to English until its template/copy package is installed.
func publicCopyFor(locale string) publicCopy {
	code := strings.ToLower(strings.Split(strings.TrimSpace(locale), "-")[0])
	copy, ok := publicCopies[code]
	if !ok {
		copy = publicCopies["en"]
		code = "en"
	}
	copy.Services = homeServices[code]
	copy.TrustItems = homeTrustItems[code]
	copy.AdvantagesTitle = homeAdvantages[code].Title
	copy.Advantages = homeAdvantages[code].Items
	copy.ProcessTitle = homeProcess[code].Title
	copy.ProcessBody = homeProcess[code].Body
	copy.ProcessSteps = homeProcess[code].Steps
	markers := []string{"01", "02", "03", "04"}
	if code == "it" {
		markers = []string{"I", "II", "III", "IV"}
	}
	for i := range copy.ProcessSteps {
		copy.ProcessSteps[i].Marker = markers[i]
	}
	copy.IndustriesTitle = homeIndustries[code].Title
	copy.IndustriesBody = homeIndustries[code].Body
	copy.Industries = homeIndustries[code].Items
	copy.FAQTitle = homeFAQs[code].Title
	copy.FAQs = homeFAQs[code].Items
	copy.PageHome, copy.PageServices, copy.PageIndustries, copy.PageSolutions = fixedPageLabels[code][0], fixedPageLabels[code][1], fixedPageLabels[code][2], fixedPageLabels[code][3]
	copy.PageWorkflow, copy.PageScope, copy.PageGuides, copy.PageContact = fixedPageLabels[code][4], fixedPageLabels[code][5], fixedPageLabels[code][6], fixedPageLabels[code][7]
	copy.PageDecision, copy.PageFits, copy.PageNeeds, copy.PageBenefits = fixedPageLabels[code][8], fixedPageLabels[code][9], fixedPageLabels[code][10], fixedPageLabels[code][11]
	copy.PageIncluded, copy.PageConfirm, copy.PageFAQTitle, copy.PageFAQLead = fixedPageLabels[code][12], fixedPageLabels[code][13], fixedPageLabels[code][14], fixedPageLabels[code][15]
	copy.PageRelatedBack, copy.PageBackTop, copy.PageRelatedTitle = fixedPageLabels[code][16], fixedPageLabels[code][17], fixedPageLabels[code][18]
	copy.FixedFooter = fixedFooter[code]
	return copy
}

