func guideIndexCopyFor(locale string) publicGuideIndexCopy {
	code := strings.ToLower(strings.Split(strings.TrimSpace(locale), "-")[0])
	if value, ok := guideIndexCopies[code]; ok {
		return value
	}
	return guideIndexCopies["en"]
}

