var homeFAQs = map[string]homeFAQText{
	"en": {Title: "Questions before you ship", Items: []publicFAQItem{{Question: "Can I start with only a product link?", Answer: "Yes. A link, photo or short specification is enough for an initial sourcing conversation; quantities and destination can follow."}, {Question: "Can you combine sourcing and fulfillment?", Answer: "The homepage should present them as one coordinated workflow, with the final scope confirmed in the shipment plan."}, {Question: "Do you provide customs clearance?", Answer: "We coordinate the information and handoffs; the site must identify the responsible broker and jurisdiction before making a clearance claim."}, {Question: "Can I request a single service?", Answer: "Yes. The form lets visitors select sourcing, transport, storage, branding, fulfillment or a combined plan."}}},
	"de": {Title: "Fragen vor dem Versand?", Items: []publicFAQItem{{Question: "Kann ich mit einem Produktlink starten?", Answer: "Ja. Link, Foto oder Spezifikation reichen für die erste Anfrage."}, {Question: "Planen Sie auch einzelne Leistungen?", Answer: "Ja. Das Formular lässt Beschaffung, Transport, Lager, Verpackung, Fulfillment oder eine Kombination auswählen."}, {Question: "Übernehmen Sie die Zollabfertigung?", Answer: "Wir koordinieren Angaben und Übergaben; die zuständige Abfertigungsstelle muss je Sendung bestätigt werden."}, {Question: "Welche Angaben beschleunigen die Antwort?", Answer: "Start, Ziel, Menge, gewünschter Termin, Produktart und vorhandene Dokumente."}}},
	"fr": {Title: "Des questions avant d’expédier ?", Items: []publicFAQItem{{Question: "Puis-je commencer avec une simple URL produit ?", Answer: "Oui. Un lien, une photo ou une courte fiche permet d’ouvrir l’échange."}, {Question: "Proposez-vous une seule étape ou un parcours complet ?", Answer: "Les deux : le formulaire permet de sélectionner sourcing, transport, stockage, marque, fulfilment ou une combinaison."}, {Question: "Gérez-vous le dédouanement ?", Answer: "Nous préparons les informations et les relais ; le courtier et la juridiction doivent être confirmés pour chaque dossier."}, {Question: "Que faut-il indiquer dans la demande ?", Answer: "Origine, destination, quantité, produit, échéance souhaitée et documents déjà disponibles."}}},
	"es": {Title: "¿Dudas antes de enviar?", Items: []publicFAQItem{{Question: "¿Puedo empezar con un enlace de producto?", Answer: "Sí. Un enlace, foto o descripción corta es suficiente para iniciar."}, {Question: "¿Puedo contratar solo una parte?", Answer: "Sí. El formulario permite seleccionar sourcing, transporte, almacén, packaging, fulfillment o un plan combinado."}, {Question: "¿Incluye despacho de aduanas?", Answer: "Coordinamos información y relevos; el agente responsable debe confirmarse para cada operación."}, {Question: "¿Qué datos aceleran la respuesta?", Answer: "Producto, cantidad, origen, destino, fecha objetivo y documentos disponibles."}}},
	"it": {Title: "Dubbi prima di spedire?", Items: []publicFAQItem{{Question: "Posso iniziare da un semplice link?", Answer: "Sì. Un link, una foto o una breve scheda aprono la conversazione."}, {Question: "Posso chiedere una sola soluzione?", Answer: "Sì. Il form permette di scegliere sourcing, trasporto, magazzino, packaging, fulfillment o un percorso completo."}, {Question: "Gestite lo sdoganamento?", Answer: "Organizziamo dati e passaggi; broker e autorità vanno confermati per ogni pratica."}, {Question: "Quali dati servono?", Answer: "Prodotto, quantità, origine, destinazione, data desiderata e documenti disponibili."}}},
	"nl": {Title: "Welke vragen spelen vóór de eerste overdracht?", Items: []publicFAQItem{{Question: "Kan ik met alleen een productlink beginnen?", Answer: "Ja. Een link, foto of korte specificatie is genoeg voor een eerste gesprek."}, {Question: "Kan ik één onderdeel aanvragen?", Answer: "Ja. Kies sourcing, transport, opslag, verpakking, fulfillment of een gecombineerde route."}, {Question: "Regelen jullie de inklaring?", Answer: "We coördineren gegevens en overdrachten; de verantwoordelijke broker moet per zending worden bevestigd."}, {Question: "Welke gegevens helpen het snelst?", Answer: "Product, hoeveelheid, vertrekpunt, bestemming, gewenste datum en beschikbare documenten."}}},
}

